// Protocol integration fixture generated by RTKLIB's encoder. This checks the
// stream/ROS path; it is not independent validation of the RTCM encoder itself.
#include <cstdio>
#include <cstring>
#include <initializer_list>
#include <stdexcept>
extern "C" {
#include "rtklib.h"
}
int main(int argc, char **argv) {
  if (argc != 2 && (argc != 3 || (std::strcmp(argv[2], "navigation") && std::strcmp(argv[2], "glonass"))))
    return 2;
  FILE *out = std::fopen(argv[1], "wb");
  if (!out)
    return 1;
  rtcm_t rtcm{};
  if (!init_rtcm(&rtcm))
    return 1;
  rtcm.time = gpst2time(2300, 100.0);
  rtcm.staid = 42;
  if (argc == 3 && !std::strcmp(argv[2], "glonass")) {
    rtcm.obs.n = 1;
    auto& obs = rtcm.obs.data[0]; obs.sat = satno(SYS_GLO, 1);
    obs.code[0] = CODE_L1C; obs.P[0] = 21000000.125; obs.SNR[0] = 45.;
    for (int channel : {-7, 0, 6}) {
      rtcm.nav.glo_fcn[0] = channel + 8;
      obs.time = rtcm.time = gpst2time(2300, 107. + channel);
      obs.L[0] = obs.P[0] * (1602e6 + channel * .5625e6) / CLIGHT;
      if (!gen_rtcm3(&rtcm, 1087, 0, 0)) return 1;
      if (std::fwrite(rtcm.buff, 1, rtcm.nbyte, out) != static_cast<size_t>(rtcm.nbyte)) return 1;
    }
    free_rtcm(&rtcm);
    return std::fclose(out) == 0 ? 0 : 1;
  }
  if (argc == 3) {
    for (int sys : {SYS_GPS, SYS_GAL}) {
      rtcm.ephsat = satno(sys, 1);
      auto& e = rtcm.nav.eph[rtcm.ephsat - 1];
      e.sat = rtcm.ephsat; e.week = 2300;
      e.toe = e.toc = e.ttr = gpst2time(2300, 120.);
      e.toes = 120.; e.A = 26560000.; e.e = .01; e.i0 = .95;
      for (int iod : {255, 256, 1023}) {
      if (sys == SYS_GPS && iod != 255) continue;
      e.iode = sys == SYS_GAL ? iod : 7; e.iodc = 7;
      if (!gen_rtcm3(&rtcm, sys == SYS_GAL ? 1046 : 1019, 0, 0)) return 1;
      if (std::fwrite(rtcm.buff, 1, rtcm.nbyte, out) != static_cast<size_t>(rtcm.nbyte)) return 1;
      }
    }
  }
  if (argc == 3) {
    rtcm.ephsat=satno(SYS_GLO,1);
    auto& g=rtcm.nav.geph[0];g.sat=rtcm.ephsat;
    g.toe=g.tof=gpst2time(2300,18.);g.frq=-7;g.sva=7;g.flags=511;g.svh=8;
    g.pos[0]=19000000.;
    if (!gen_rtcm3(&rtcm,1020,0,0)) return 1;
    if (std::fwrite(rtcm.buff,1,rtcm.nbyte,out)!=static_cast<size_t>(rtcm.nbyte)) return 1;
  }
  rtcm.obs.n = 2;
  for (int i = 0; i < 2; ++i) {
    auto &obs = rtcm.obs.data[i];
    obs.time = rtcm.time;
    obs.sat = satno(i == 0 ? SYS_GPS : SYS_GAL, 1);
    obs.code[0] = CODE_L1C;
    obs.P[0] = 21000000.125;
    obs.L[0] = obs.P[0] / (CLIGHT / FREQL1);
    obs.D[0] = -1234.5;
    obs.SNR[0] = 45.0f;
  }
  for (int type : {1077, 1097}) {
    if (!gen_rtcm3(&rtcm, type, 0, type == 1077))
      return 1;
    if (std::fwrite(rtcm.buff, 1, rtcm.nbyte, out) !=
        static_cast<size_t>(rtcm.nbyte))
      return 1;
  }
  free_rtcm(&rtcm);
  return std::fclose(out) == 0 ? 0 : 1;
}
